// snapshot_main.cpp - headless UI snapshot of a "camel synth" plugin editor.
//
// This file is project agnostic. Everything project specific arrives as compile
// definitions generated by render.sh (which auto-detects them from the project):
//
//   SNAP_PROC_CLASS     fully qualified processor class   (e.g. AbProcessor, Wz::WarzoneProcessor)
//   SNAP_EDITOR_CLASS   fully qualified editor class      (only used for a sanity check)
//   SNAP_APPLY_METHOD   processor method taking an int preset index (applyPreset / setCurrentProgram ...)
//   SNAP_DEFAULT_W/H    editor default size found in PluginEditor.{h,cpp} (fallback only)
//
// Usage:  Snapshot <out.png> [presetIndex] [--scale=1.5] [--size=WxH] [--settle=ms] [--keep-resizer]
//   exit codes: 0 ok, 1 usage, 2 bad preset index, 3 no editor, 4 write error
//
// Pixel size of the PNG = editor size * scale (default 1000x746 * 1.5 = 1500x1119).

#include "PluginEditor.h"   // every project's editor header pulls in its processor header
#include <cstdio>

#ifndef SNAP_PROC_CLASS
 #error "SNAP_PROC_CLASS not defined - run through render.sh"
#endif
#ifndef SNAP_APPLY_METHOD
 #define SNAP_APPLY_METHOD setCurrentProgram
#endif
#define SNAP_STR2(x) #x
#define SNAP_STR(x) SNAP_STR2(x)
#ifndef SNAP_DEFAULT_W
 #define SNAP_DEFAULT_W 1000
#endif
#ifndef SNAP_DEFAULT_H
 #define SNAP_DEFAULT_H 746
#endif

namespace
{
    bool parseSize (const juce::String& s, int& w, int& h)
    {
        const auto t = s.trim();
        const int x = t.indexOfAnyOf ("xX,");
        if (x <= 0) return false;
        w = t.substring (0, x).getIntValue();
        h = t.substring (x + 1).getIntValue();
        return w > 0 && h > 0;
    }

    int usage()
    {
        std::fprintf (stderr, "usage: Snapshot <out.png> [presetIndex] [--scale=1.5] [--size=WxH] [--settle=ms] [--keep-resizer]\n");
        return 1;
    }
}

int main (int argc, char** argv)
{
    juce::String outPath;
    int preset = 0;
    float scale = 1.5f;
    int forcedW = 0, forcedH = 0;
    int settleMs = 150;
    bool keepResizer = false;
    int positional = 0;

    for (int i = 1; i < argc; ++i)
    {
        const juce::String a (argv[i]);
        if (a.startsWith ("--scale="))       scale = a.fromFirstOccurrenceOf ("=", false, false).getFloatValue();
        else if (a.startsWith ("--size="))   { if (! parseSize (a.fromFirstOccurrenceOf ("=", false, false), forcedW, forcedH)) return usage(); }
        else if (a.startsWith ("--settle=")) settleMs = a.fromFirstOccurrenceOf ("=", false, false).getIntValue();
        else if (a == "--keep-resizer")      keepResizer = true;
        else if (a.startsWith ("--"))        return usage();
        else if (positional == 0)            { outPath = a; ++positional; }
        else if (positional == 1)            { preset = a.getIntValue(); ++positional; }
        else                                 return usage();
    }
    if (outPath.isEmpty() || scale <= 0.f) return usage();

    juce::ScopedJuceInitialiser_GUI init;
    SNAP_PROC_CLASS proc;

    const int numPresets = proc.getNumPrograms();
    if (preset < 0 || (numPresets > 0 && preset >= numPresets))
    {
        std::fprintf (stderr, "error: preset index %d out of range (0..%d)\n", preset, numPresets - 1);
        return 2;
    }
    proc.SNAP_APPLY_METHOD (preset);
    proc.prepareToPlay (48000.0, 512);

    std::unique_ptr<juce::AudioProcessorEditor> ed (proc.createEditor());
    if (ed == nullptr)
    {
        std::fprintf (stderr, "error: createEditor() returned null\n");
        return 3;
    }

#ifdef SNAP_EDITOR_CLASS
    if (dynamic_cast<SNAP_EDITOR_CLASS*> (ed.get()) == nullptr)
        std::fprintf (stderr, "warning: editor is not a %s (auto-detected class name looks wrong)\n", SNAP_STR (SNAP_EDITOR_CLASS));
#endif

    // size: --size / SNAP_SIZE > size chosen by the editor constructor > size parsed from the sources > 1000x746
    int w = ed->getWidth(), h = ed->getHeight();
    if (forcedW > 0) { w = forcedW; h = forcedH; }
    else if (w <= 0 || h <= 0) { w = SNAP_DEFAULT_W; h = SNAP_DEFAULT_H; }
    else if (w != SNAP_DEFAULT_W || h != SNAP_DEFAULT_H)
        std::fprintf (stderr, "note: editor opens at %dx%d, sources suggested %dx%d - using the editor's own size\n", w, h, (int) SNAP_DEFAULT_W, (int) SNAP_DEFAULT_H);
    if (ed->getWidth() != w || ed->getHeight() != h) ed->setSize (w, h);

    // let async updates (preset label, attachments, deferred layout) run before we grab the pixels
    if (settleMs > 0)
        juce::MessageManager::getInstance()->runDispatchLoopUntil (settleMs);

    // the host-resize grip (bottom-right corner) is editor chrome, not product UI: hide it for marketing shots
    if (! keepResizer)
        for (auto* child : ed->getChildren())
            if (dynamic_cast<juce::ResizableCornerComponent*> (child) != nullptr)
                child->setVisible (false);

    auto img = ed->createComponentSnapshot (ed->getLocalBounds(), true, scale);

    juce::File f (juce::File::getCurrentWorkingDirectory().getChildFile (outPath));
    f.getParentDirectory().createDirectory();
    f.deleteFile();
    bool ok = false;
    {
        juce::FileOutputStream os (f);
        if (os.openedOk())
        {
            juce::PNGImageFormat png;
            ok = png.writeImageToStream (img, os);
            os.flush();
        }
    }
    if (! ok)
    {
        std::fprintf (stderr, "error: could not write %s\n", f.getFullPathName().toRawUTF8());
        return 4;
    }

    std::printf ("wrote %s  %dx%d px  (editor %dx%d @ x%.2f)  preset %d/%d \"%s\"\n",
                 f.getFullPathName().toRawUTF8(), img.getWidth(), img.getHeight(), w, h, (double) scale,
                 preset, numPresets, proc.getProgramName (preset).toRawUTF8());

    ed.reset();
    return 0;
}
